class WebhookVaga {
  private static final Set<String> HOSTS = Set.of("hooks.parceiro.com.br");
  void disparar(HttpClient c, HttpServletRequest request) throws Exception {
    URI u = new URI(request.getParameter("callback"));
    if (!"https".equals(u.getScheme()) || !HOSTS.contains(u.getHost())) throw new SecurityException("destino");
    c.send(HttpRequest.newBuilder(u).build(), HttpResponse.BodyHandlers.discarding());
  }
}

